{
  "points": [
    {
      "grammar_point": "Infinitive complement after a noun",
      "sentence": "Trump is under heavy pressure to maintain the ceasefire, and potentially make a peace deal, before a scheduled visit this week to China, which is pushing for an end to hostilities and the opening of the strait.",
      "explanation": "En español, la forma 'to maintain...' es un infinitivo que funciona como complemento del sustantivo 'pressure', indicando la acción que se espera."
    },
    {
      "grammar_point": "Relative clause introduced by 'which'",
      "sentence": "Trump is under heavy pressure to maintain the ceasefire, and potentially make a peace deal, before a scheduled visit this week to China, which is pushing for an end to hostilities and the opening of the strait.",
      "explanation": "El pronombre relativo 'which' introduce una cláusula que da información adicional sobre 'China', equivalente a 'la cual' en español."
    }
  ]
}

