message.content:
{
  "points": [
    {
      "grammar_point": "Modal verb for prohibition (may not)",
      "sentence": "You may not publish or post other people's private information ...",
      "explanation": "En inglés, el modal 'may not' se usa para expresar una prohibición. Indica que la acción está prohibida."
    },
    {
      "grammar_point": "Gerund after the verb 'prohibit'",
      "sentence": "We also prohibit threatening to expose private information or incentivizing others to do so.",
      "explanation": "Después del verbo 'prohibit' se emplea un gerundio ('threatening') para describir la acción que se prohíbe, manteniendo la estructura paralela con 'incentivizing'."
    }
  ]
}

