message.content:
{
  "points": [
    {
      "grammar_point": "Oración temporal con 'before' y pasado simple",
      "sentence": "Ten months passed before my father discovered where he lived.",
      "explanation": "En español, la conjunción 'before' introduce una cláusula temporal que indica que una acción ocurre después de otra. Se traduce como 'antes de que' o 'antes de', y ambas verbos van en pasado simple, como en 'antes de que mi padre descubriera dónde vivía'."
    },
    {
      "grammar_point": "Frases participiales (participio pasado y gerundio) como modificadores",
      "sentence": "He found his old friend sunk in his grief, lying in bed, incapable of any activity.",
      "explanation": "Las frases 'sunk in his grief', 'lying in bed' e 'incapable of any activity' son construcciones noiales que describen al sustantivo 'friend'. En español se traducen como cláuspos adjetivales o gerundios: 'sumido en su dolor, acostado en la cama, incapaz de cualquier actividad'."
    }
  ]
}

