message.content:
{
  "points": [
    {
      "grammar_point": "Modal verb + bare infinitive (could determine)",
      "sentence": "Arsenal’s manager ... said the decision on Sunday could determine “the history of two massive clubs ...”",
      "explanation": "El modal ‘could’ indica posibilidad. Va seguido de un infinitivo sin ‘to’ (determine). En español se traduce como ‘podría determinar’."
    },
    {
      "grammar_point": "Relative clause with present progressive (that are fighting)",
      "sentence": "… “the history of two massive clubs that are fighting with their lives to achieve their objectives” …",
      "explanation": "La cláusula relativa introducida por ‘that’ describe a los clubes y usa el presente continuo ‘are fighting’ para expresar una acción en curso. En español sería ‘que están luchando’."
    }
  ]
}

