message.content:
{
  "points": [
    {
      "grammar_point": "Compound noun with past‑participle modifier (ranch‑turned‑hotel)",
      "sentence": "At Las Torres Patagonia, a historic ranch-turned-hotel within the park, 150 horses roam freely across 14,800 acres of land before being gathered at dawn for guest rides.",
      "explanation": "En inglés se pueden crear sustantivos compuestos usando un participio pasado como modificador, unido por guion. Aquí ‘ranch‑turned‑hotel’ indica que el rancho se ha convertido en hotel. El participio ‘turned’ funciona como adjetivo que describe al sustantivo ‘ranch’."
    },
    {
      "grammar_point": "Non‑defining relative clause with present perfect passive + infinitive list",
      "sentence": "the experiences draw on the therapeutic power of spending time with horses, which has been shown to ease anxiety, improve emotional awareness and build self-esteem.",
      "explanation": "La cláusula relativa ‘which has been shown …’ es no restrictiva (se separa con coma) y utiliza el presente perfecto pasivo ‘has been shown’. Después sigue una serie de infinitivos (‘to ease’, ‘improve’, ‘build’) que describen los efectos del estudio. En español se traduciría como ‘lo cual ha demostrado que alivia…’."
    }
  ]
}

